Bash(gh api graphql -f query='
mutation {
  updateProjectV2SingleSelectField\(input: {
    projectId: "PVT_kwDOBQg2P84BQK7F"
    fieldId: "PVTSSF_lADOBQg2P84BQK7Fzg-XiZY"
    singleSelectOptions: [
      { name: "Backlog", color: GRAY, description: "Not yet prioritized" }
      { name: "Up Next", color: BLUE, description: "Queued for active sprint" }
      { name: "In Progress", color: YELLOW, description: "Actively being worked on" }
      { name: "Done", color: GREEN, description: "Completed" }
